  // ── Проверить документы ────────────────────────────────────────────
  const checks: { state: 'ok' | 'warn' | 'info'; label: string; value: string }[] = []
  const year = i.yearRaw && /^\d{4}$/.test(i.yearRaw.trim()) ? Number(i.yearRaw.trim()) : null
  const built = !!i.status && /построен|ready|completed|сдан/i.test(i.status)
  if (i.status) checks.push({ state: built ? 'ok' : 'info', label: T('Стройка', 'Construction', { id: 'Pembangunan', fr: 'Construction', de: 'Bau', zh: '建设进度', nl: 'Bouw', ban: 'Pembangunan', pl: 'Budowa', uk: 'Будівництво' }), value: built ? T(year ? `завершена в ${year}` : 'завершена', year ? `completed in ${year}` : 'completed', { id: year ? `selesai pada ${year}` : 'selesai', fr: year ? `achevée en ${year}` : 'achevée', de: year ? `fertiggestellt ${year}` : 'fertiggestellt', zh: year ? `${year} 年竣工` : '已竣工', nl: year ? `voltooid in ${year}` : 'voltooid', ban: year ? `puput ring ${year}` : 'sampun puput', pl: year ? `zakończona w ${year} r.` : 'zakończona', uk: year ? `завершено в ${year}` : 'завершено' }) : stTxt(i.status) })
  const nowYear = new Date().getFullYear()
  if (i.leaseYears != null) checks.push({ state: i.leaseYears >= 20 ? 'ok' : 'warn', label: T('Аренда земли', 'Land lease', { id: 'Sewa tanah', fr: 'Bail foncier', de: 'Grundstückspacht', zh: '土地租赁', nl: 'Grondpacht', ban: 'Sewa tanah', pl: 'Dzierżawa gruntu', uk: 'Оренда землі' }), value: T(`${Math.round(i.leaseYears)} лет`, `${Math.round(i.leaseYears)} years`, { id: `${Math.round(i.leaseYears)} tahun`, fr: `${Math.round(i.leaseYears)} ans`, de: `${Math.round(i.leaseYears)} Jahre`, zh: `${Math.round(i.leaseYears)} 年`, nl: `${Math.round(i.leaseYears)} jaar`, ban: `${Math.round(i.leaseYears)} taun`, pl: `${Math.round(i.leaseYears)} ${plp(i.leaseYears, 'rok|lata|lat')}`, uk: `${Math.round(i.leaseYears)} ${plw(i.leaseYears, 'рік|роки|років')}` }) })
